mapper.update:
UPDATE destination
SET view_count = view_count + 1
WHERE contentid = #{contentid}

mapper.select:
SELECT * FROM ( SELECT inner_query.*, ROWNUM AS rn FROM ( SELECT d.contentid AS "contentid", d.contenttypeid AS "contenttypeid", d.title AS "title", d.addr1 AS "addr1", d.firstimage AS "firstimage", d.view_count AS "viewCount", r.regn_name AS "regnName", s.signgu_name AS "signguName", NVL(rv.avg_rating, 0) AS "averageRating", NVL(rv.review_count, 0) AS "reviewCount" FROM destination d LEFT JOIN ldong_regn_code r ON d.lDongRegnCd = r.lDongRegnCd LEFT JOIN ldong_signgu_code s ON d.lDongRegnCd = s.lDongRegnCd AND d.lDongSignguCd = s.lDongSignguCd LEFT JOIN ( SELECT contentid, ROUND(AVG(rv_rating), 1) AS avg_rating, COUNT(*) AS review_count FROM review GROUP BY contentid ) rv ON d.contentid = rv.contentid
AND d.contenttypeid = #{contenttypeid}
AND d.contenttypeid NOT IN ('15', '25')
AND d.lDongRegnCd = #{lDongRegnCd}
AND INSTR(',' || #{lDongSignguCd} || ',', ',' || d.lDongSignguCd || ',') > 0
ORDER BY CASE WHEN d.firstimage2 IS NOT NULL AND d.firstimage2 != ' ' AND d.overview IS NOT NULL THEN 1 WHEN d.firstimage2 IS NOT NULL AND d.firstimage2 != ' ' THEN 2 WHEN d.overview IS NOT NULL THEN 3 ELSE 4 END ASC,
d.view_count DESC NULLS LAST, d.contentid DESC
d.modifiedtime DESC NULLS LAST, d.contentid DESC
) inner_query WHERE ROWNUM <= #{offset} + #{limit} ) WHERE rn > #{offset}

SELECT COUNT(*) FROM destination d



            AND d.contenttypeid = #{contenttypeid}


            AND d.contenttypeid NOT IN ('15', '25')



        AND d.lDongRegnCd = #{lDongRegnCd}


        AND INSTR(',' || #{lDongSignguCd} || ',', ',' || d.lDongSignguCd || ',') > 0

SELECT * FROM ( SELECT inner_query.*, ROWNUM AS rn FROM ( SELECT d.contentid AS "contentid", d.contenttypeid AS "contenttypeid", d.title AS "title", d.addr1 AS "addr1", d.firstimage AS "firstimage", d.view_count AS "viewCount", r.regn_name AS "regnName", s.signgu_name AS "signguName", NVL(rv.avg_rating, 0) AS "averageRating", NVL(rv.review_count, 0) AS "reviewCount" FROM destination d LEFT JOIN ldong_regn_code r ON d.lDongRegnCd = r.lDongRegnCd LEFT JOIN ldong_signgu_code s ON d.lDongRegnCd = s.lDongRegnCd AND d.lDongSignguCd = s.lDongSignguCd LEFT JOIN ( SELECT contentid, ROUND(AVG(rv_rating), 1) AS avg_rating, COUNT(*) AS review_count FROM review GROUP BY contentid ) rv ON d.contentid = rv.contentid WHERE (d.title LIKE '%' || #{keyword} || '%' OR d.addr1 LIKE '%' || #{keyword} || '%')
AND d.lDongRegnCd = #{lDongRegnCd}
AND INSTR(',' || #{lDongSignguCd} || ',', ',' || d.lDongSignguCd || ',') > 0
ORDER BY CASE WHEN d.firstimage2 IS NOT NULL AND d.firstimage2 != ' ' AND d.overview IS NOT NULL THEN 1 WHEN d.firstimage2 IS NOT NULL AND d.firstimage2 != ' ' THEN 2 WHEN d.overview IS NOT NULL THEN 3 ELSE 4 END ASC, d.view_count DESC NULLS LAST, d.title ASC ) inner_query WHERE ROWNUM <= #{offset} + #{limit} ) WHERE rn > #{offset}

